// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 warpTime, uint256 unlockTime, address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.warp(bound(warpTime, 1, 2 ** 100));
        unlockTime = bound(unlockTime, block.timestamp + 1, 2 ** 120);
        amount = bound(amount, 1, 2 ** 100);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // Rule: after Put(t) with t > now, the stored unlock time must be at least t.
        assertTrue(__invmut_c_Acc_unlockTime(actor) >= unlockTime);
    }

    function __invmut_c_Acc_unlockTime(address __k) internal view returns (uint256) {
        (uint256 _v0, ) = c.Acc(__k);
        return _v0;
    }
}
